/// <summary>
/// Controller for the multithreaded batch monitoring test job.
/// </summary>
class METBatchMonitoringTestMultiController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Wires the controller to the service class and method.
/// </summary>
protected void new()
{
    super(classStr(METBatchMonitoringTestMultiService), methodStr(METBatchMonitoringTestMultiService, process), SysOperationExecutionMode::Synchronous);
}

public static METBatchMonitoringTestMultiController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METBatchMonitoringTestMultiController controller = new METBatchMonitoringTestMultiController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

public static void main(Args _args)
{
    METBatchMonitoringTestMultiController controller = METBatchMonitoringTestMultiController::construct(_args);
    controller.batchInfo().parmBatchExecute(true);
    controller.startOperation();
}
